object FakeEventsRepository {
    private fun ev(
        n: Int, interest: Interest, title: String, startsAt: String, place: String,
        address: String, price: String?, url: String, source: String,
        city: String = "astana",
        kk: Pair<String, String>? = null, // (title, place) in Kazakh, for generated city templates
        en: Pair<String, String>? = null,
        desc: Descriptions.Text? = null, // explicit text for generated city templates
    ): EventCard {
        val id = if (city == "astana") "demo-$n" else "$city-$n"
        val d = desc ?: Descriptions.forId(id)
        return EventCard(
        id = id, cityId = city,
        titleRu = title, titleKk = kk?.first ?: Translations.kk(title), titleEn = en?.first ?: Translations.en(title),
        startsAt = startsAt,
        placeRu = place, placeKk = kk?.second ?: Translations.kk(place), placeEn = en?.second ?: Translations.en(place),
        address = address,
        interest = interest, price = price,
        whyMatches = "Интерес: ${interest.labelRu.lowercase()}",
        sourceUrl = url, sourceName = source,
        workingHours = eventHours(startsAt, place, interest),
        descriptionRu = d?.ru.orEmpty(), descriptionKk = d?.kk.orEmpty(), descriptionEn = d?.en.orEmpty(),
        )
    }

    private fun eventHours(startsAt: String, place: String, interest: Interest): String {
        val m = Regex("(\\d{1,2}):(\\d{2})").findAll(startsAt).lastOrNull()
        val h = m?.groupValues?.get(1)?.toInt() ?: 10
        val mm = m?.groupValues?.get(2) ?: "00"
        val pl = place.lowercase()
        return when {
            interest == Interest.EXHIBITIONS || "музей" in pl -> "Касса 10:00–18:00, Пн — выходной"
            h >= 17 -> "Вход за 30 мин · %02d:%s–%02d:%s".format(h, mm, (h + 2) % 24, mm)
            else -> "%02d:%s–%02d:%s".format(h, mm, (h + 3) % 24, mm)
        }
    }

    // BEGIN GENERATED by tools/gen_feed.py
    private fun real(
        id: String, city: String, interest: Interest, isPlace: Boolean,
        tRu: String, tKk: String, tEn: String, startsAt: String,
        pRu: String, pKk: String, pEn: String, address: String, price: String?,
        url: String, source: String, hours: String, lat: Double?, lon: Double?,
    ): EventCard {
        val d = Descriptions.forId(id)
        return EventCard(
            id = id, cityId = city, titleRu = tRu, titleKk = tKk, titleEn = tEn, startsAt = startsAt,
            placeRu = pRu, placeKk = pKk, placeEn = pEn, address = address, interest = interest, price = price,
            whyMatches = "Интерес: ${interest.labelRu.lowercase()}", sourceUrl = url, sourceName = source,
            isPlace = isPlace, workingHours = hours,
            descriptionRu = d?.ru.orEmpty(), descriptionKk = d?.kk.orEmpty(), descriptionEn = d?.en.orEmpty(),
            lat = lat, lon = lon,
        )
    }

