    fun forCity(city: City): List<EventCard> = when (city.id) {
        "astana" -> astana
        "almaty" -> almaty
        "shymkent" -> shymkent
        else -> template(city)
    }

    fun forProfile(profile: UserProfile, city: City, hidden: Set<String>): List<EventCard> =
        forCity(city).filter { it.interest in profile.interests && it.id !in hidden }
